/* Capa de RELATÓRIO DE TECNOLOGIA — os elementos da capa que o time já usa.
 *
 * As imagens vêm da própria apresentação mensal (a foto de fundo, os selos Great
 * Place To Work e a assinatura de 10 anos), reduzidas para o tamanho em que são
 * projetadas: 1600px de largura na foto, que é o dobro do que um projetor
 * mostra, e PNG nos dois elementos com transparência.
 *
 * Ficam em arquivo separado, e não dentro de apresentacao.js, por um motivo
 * prático: são 131 KB de base64 que ninguém precisa reler ao mexer na lógica dos
 * slides — e o navegador guarda este arquivo em cache entre as gerações.
 *
 * Trocou a identidade? Só este arquivo muda.
 */
window.CAPA_TECNOLOGIA = {
  // Fundo de página inteira: leão + textura, já na proporção 16:9 do slide.
  fundo: 'data:image/jpeg;base64,',
  // Selos, canto superior direito.
  selos: 'data:image/png;base64,',
  // Assinatura Audax 10 anos, canto inferior direito.
  logo: 'data:image/png;base64,',
  // O verde da marca. É ele que separa "RELATÓRIO DE" e o mês do título branco.
  verde: '00FD54',
};
